import { gameConfig } from "game/config";

import {
  GridEngineHeadless,
  Tilemap,
  GridEngineConfigHeadless,
} from "grid-engine";
import { Box, CharactersState, LoaderResources, SceneConfig } from "type";
import { Player } from "../Character";
import { playerManager } from "managers/PlayerManager";
import { between, getRandomArrayElements } from "utils";
import { playerConfig } from "managers/config";
import { lockedRandomItems, simpleRandomItems } from "items";
import { Pointer } from "./modules";

export class GameScene extends Phaser.Scene {
  gridEngine!: GridEngineHeadless;

  constructor(loaderResources: LoaderResources, config: SceneConfig) {
    super();

    const { boxes = [] } = config || {};

    this.boxes.prepared = boxes;
    this.sceneConfig = config;
    this.loaderResources = loaderResources;
  }

  private sceneConfig: SceneConfig;
  cellSize = 0;

  cursors?: Phaser.Types.Input.Keyboard.CursorKeys;
  tilemap?: Phaser.Tilemaps.Tilemap;

  characters: CharactersState = {
    NPC: {},
    enemy: {},
  } as CharactersState;
  camera?: Phaser.Cameras.Scene2D.Camera;
  /**coordinates as "x|y" */
  boxes: {
    prepared: Box[];
    state: Record<string, Box>;
  } = { prepared: [], state: {} };

  private loaderResources: LoaderResources;

  preload() {
    Object.keys(this.loaderResources).forEach((key) => {
      const method = key as keyof LoaderResources;
      const values = this.loaderResources[method];
      //@ts-ignore
      this.load[method](...values);
    });
  }

  private createCharacters(tilemap: Phaser.Tilemaps.Tilemap) {
    const { characters } = this.sceneConfig;
    console.log("🚀 ~ file: index.ts:59 ~ GameScene ~ createCharacters ~ characters:", characters)
    const { player: playerConfig } = characters;
    const { charactersScale, mapScale } = gameConfig.scale;

    const player = new Player(this, playerConfig.sprite);
    this.characters.player = player;

    player.sprite.scale = charactersScale;
    this.camera = this.cameras.main;

    this.camera.setBounds(
      0,
      0,
      tilemap.widthInPixels * mapScale,
      tilemap.heightInPixels * mapScale,
    );
    this.camera.startFollow(player.sprite, true);

    return {
      player,
    };
  }

  private createBoxes(layers: Phaser.Tilemaps.TilemapLayer[]) {
    // requestAnimationFrame(() => {
    let boxIndex = 0;

    layers.forEach((layer) => {
      layer.layer.data.forEach((line, i) => {
        line.forEach((tile) => {
          if (tile.properties.box) {
            const currentBox = this.boxes.prepared[boxIndex];
            const id = `${tile.x}|${tile.y}`;
            if (currentBox) {
              this.boxes.state[id] = currentBox;
            } else {
              // The box is not defined. It must be filled with random items
              const isLock = !(
                between(0, 100) <= gameConfig.gamePlay.randomBoxLockChance
              );

              const lock = isLock
                ? 0
                : between(0, playerConfig.skillsMaximumLevel.lockBreaking);

              const itemsAmount = between(
                1,
                gameConfig.gamePlay.randomItemsMaxAmount,
              );

              this.boxes.state[id] = {
                lock,
                items: getRandomArrayElements(
                  lock ? lockedRandomItems : simpleRandomItems,
                  itemsAmount,
                ),
              };
            }

            boxIndex++;
          }
        });
      });
    });
    // });

    console.log(">", this.boxes);
  }

  create() {
    const { characters } = this.sceneConfig;
    const { player: playerConfig } = characters;
    const { names, scale } = gameConfig;

    this.tilemap = this.make.tilemap({
      //@ts-ignore
      key: this.loaderResources.tilemapTiledJSON[0],
    });
    this.tilemap.addTilesetImage(names.mainMapTile, "tiles");

    const worldScale = scale.mapScale;
    this.cellSize = this.tilemap.tileWidth * worldScale;

    const layers: Phaser.Tilemaps.TilemapLayer[] = [];

    for (let i = 0; i < this.tilemap.layers.length; i++) {
      const layer = this.tilemap.createLayer(i, names.mainMapTile, 0, 0);

      if (layer) {
        layer.scale = worldScale;
        layers.push(layer);
      }
    }

    this.createBoxes(layers);
    const { player } = this.createCharacters(this.tilemap);

    const gridEngineConfig: GridEngineConfigHeadless = {
      characters: [
        {
          id: player.spriteId,
          //@ts-ignore
          sprite: player.sprite,
          walkingAnimationMapping: 6,
          startPosition: playerConfig.startedPosition,
          speed: playerManager.getSkillValue("move"),
        },
      ],
    };

    this.gridEngine.create(
      this.tilemap as unknown as Tilemap,
      gridEngineConfig,
    );
    console.log(this.gridEngine);

    // CREATE LISTENER TO CHANGE SPEED CONFIG

    this.cursors = this.input.keyboard?.createCursorKeys();
    const pointer = new Pointer(this);

    playerManager.listenChangeValue("move", (value) => {
      this.gridEngine.setSpeed(player.spriteId, value);
    });
  }

  update(time: number, delta: number) {
    this.characters.player?.checkMovement();
  }
}
